import React, { useState } from 'react';

// === Komponen Halaman Profil (Desain Super Simple & Keren) ===
const ProfilePage = ({ data, onBack }) => (
  <div className="animate-in fade-in duration-500 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10 md:py-16 text-left">
    {/* Tombol Back Minimalis */}
    <button 
      onClick={onBack} 
      className="mb-12 flex items-center gap-2 text-slate-500 hover:text-slate-900 transition-all group font-medium text-sm"
    >
      <span className="group-hover:-translate-x-1 transition-transform">←</span>
      Back to Directory
    </button>

    <div className="grid grid-cols-1 md:grid-cols-12 gap-10 md:gap-16 items-center">
      {/* Bagian Kiri: Foto Profil Bulat Besar dengan Ring Pastel */}
      <div className="md:col-span-5 flex justify-center md:justify-end relative">
        <div className={`relative p-2 rounded-full bg-gradient-to-tr ${data.warna} shadow-lg`}>
          <div className="rounded-full overflow-hidden w-64 h-64 sm:w-80 sm:h-80 md:w-96 md:h-96 border-4 border-white bg-white">
            <img 
              src={data.foto} 
              alt={data.nama} 
              className="w-full h-full object-cover rounded-full"
            />
          </div>
        </div>
      </div>

      {/* Bagian Kanan: Informasi Detail (Clean Typo) */}
      <div className="md:col-span-7 flex flex-col justify-center">
        <div className="space-y-1 mb-8">
          <p className={`text-sm font-bold tracking-widest uppercase ${data.warnaText}`}>
            Student Profile
          </p>
          <h1 className="text-4xl sm:text-5xl md:text-6xl font-black text-slate-950 tracking-tighter leading-tight">
            {data.nama}
          }
          </h1>
          <p className="text-xl md:text-2xl font-mono text-slate-500 tracking-tight">
            ID: {data.nim}
          </p>
        </div>
        
        {/* Info Grid Minimalis */}
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-x-6 gap-y-5 mb-10 py-6 border-y border-slate-100">
          {[
            { label: 'Class', value: data.kelas },
            { label: 'Program', value: data.jurusan },
            { label: 'Location', value: data.domisili }
          ].map((item, index) => (
            <div key={index} className="space-y-1">
              <p className="text-xs text-slate-400 uppercase font-semibold tracking-wider">{item.label}</p>
              <p className="text-base text-slate-800 font-medium">{item.value}</p>
            </div>
          ))}
        </div>

        {/* Bagian Tentang Diri (Whitespace is Key) */}
        <div className="relative">
          <p className="text-slate-600 leading-relaxed text-base md:text-lg whitespace-pre-line">
            {data.tentang}
          </p>
          {/* Pastel Accent Decor */}
          <div className={`absolute -left-6 top-1 w-1 h-full rounded-full ${data.warnaBg}`}></div>
        </div>
      </div>
    </div>
  </div>
);

// === Komponen Utama App (Gallery Urut NIM) ===
export default function App() {
  const [currentPage, setCurrentPage] = useState('home');

  // DATA ANGGOTA BERDASARKAN NIM (DENGAN AKSEN WARNA PASTEL)
  const dataAnggota = [
    {
      id: "anjani-astagina",
      nama: "Anjani Astagina",
      nim: "253140700111035",
      kelas: "T2-A",
      jurusan: "Teknologi Informasi",
      domisili: "Malang",
      foto: "/images/anjani.jpeg", 
      // Pastel Blue Accents
      warna: "from-blue-200 to-cyan-100", 
      warnaText: "text-blue-500",
      warnaBg: "bg-blue-100",
      tentang: "Anjani, silakan isi biografi kamu di sini minimal 100 kata agar memenuhi syarat penilaian tugas project ini..."
    },
    {
      id: "tzurayya-aisyah",
      nama: "Tzurayya Aisyah Priantika",
      nim: "253140700111037",
      kelas: "T2-A",
      jurusan: "Teknologi Informasi",
      domisili: "Depok",
      foto: "/images/tzurayya.jpeg", 
      // Pastel Emerald Accents
      warna: "from-emerald-200 to-teal-100", 
      warnaText: "text-emerald-600",
      warnaBg: "bg-emerald-100",
      tentang: "Tzurayya, silakan isi biografi kamu di sini minimal 100 kata agar memenuhi syarat penilaian tugas project ini..."
    },
    {
      id: "tabina-naila",
      nama: "Tabina Naila Griselda",
      nim: "253140701111031",
      kelas: "T2-A",
      jurusan: "Teknologi Informasi",
      domisili: "Jombang",
      foto: "/images/tabina.jpeg",
      // Pastel Purple Accents (Warna Tabina)
      warna: "from-purple-200 to-pink-100", 
      warnaText: "text-purple-600",
      warnaBg: "bg-purple-100",
      // DESKRIPSI TABINA (Deskripsi kamu yang sama)
      tentang: "Halo! Saya adalah mahasiswi program studi Teknologi Informasi di Universitas Brawijaya yang memiliki ketertarikan mendalam pada pengembangan perangkat lunak dan desain antarmuka pengguna (UI/UX). Selama menempuh pendidikan di semester ini, saya telah mempelajari berbagai dasar pemrograman seperti ReactJS dan Tailwind CSS yang saya implementasikan langsung dalam mini project ini. \n\nSaya adalah pribadi yang senang bekerja sama dalam tim, mudah beradaptasi dengan lingkungan baru, serta memiliki rasa ingin tahu yang tinggi terhadap perkembangan teknologi masa kini. Melalui project biodata kelompok ini, saya belajar banyak mengenai kolaborasi menggunakan GitHub serta bagaimana mengelola sebuah proyek secara sistematis. Cita-cita saya adalah menjadi seorang Front-end Developer yang mampu menciptakan solusi digital inovatif dan bermanfaat bagi masyarakat luas di masa depan." 
    }
  ];

  return (
    // Background Putih Bersih
    <div className="min-h-screen bg-white font-sans text-slate-800 overflow-x-hidden relative selection:bg-purple-100 selection:text-purple-900">
      
      {currentPage === 'home' ? (
        <div className="relative z-10 text-center animate-in fade-in duration-700 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 md:py-28">
          <header className="mb-24 md:mb-32 space-y-3">
            <p className="text-purple-600 font-bold tracking-[0.3em] uppercase text-xs md:text-sm">Vokasi Universitas Brawijaya</p>
            <h1 className="text-6xl md:text-8xl font-black text-slate-950 tracking-tighter uppercase leading-none">
              Group 5<span className="text-purple-200"> Directory</span>
            </h1>
            <p className="text-lg text-slate-500 max-w-xl mx-auto">A modern showcase of our technology information student profiles, ordered by Student ID.</p>
          </header>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8 md:gap-12">
            {dataAnggota.map((item) => (
              <div 
                key={item.id} 
                onClick={() => setCurrentPage(item.id)} 
                className="group cursor-pointer bg-slate-50 border border-slate-100 hover:border-slate-200 p-8 rounded-[2rem] hover:-translate-y-3 transition-all duration-500 ease-out shadow-sm hover:shadow-xl hover:shadow-purple-50"
              >
                {/* Foto Card Bulat Minimalis */}
                <div className="relative mb-8 flex justify-center">
                  <div className={`absolute inset-0 rounded-full scale-105 blur-md ${item.warna} opacity-30 group-hover:opacity-70 transition-opacity`}></div>
                  <div className={`relative p-1 rounded-full bg-gradient-to-tr ${item.warna}`}>
                    <div className="rounded-full overflow-hidden w-40 h-40 border-4 border-white bg-white">
                      <img 
                        src={item.foto} 
                        className="w-full h-full object-cover rounded-full transition-transform duration-700 group-hover:scale-110" 
                        alt={item.nama} 
                      />
                    </div>
                  </div>
                </div>
                
                {/* Info Card Minimalis */}
                <h2 className="text-2xl font-black text-slate-950 mb-1 leading-tight tracking-tight group-hover:text-purple-700 transition-colors">
                  {item.nama}
                </h2>
                <p className="text-slate-500 text-sm font-mono tracking-tight mb-5">{item.nim}</p>
                
                <div className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-full bg-white border border-slate-100 text-xs font-bold text-slate-700 uppercase tracking-wider group-hover:bg-purple-600 group-hover:text-white group-hover:border-purple-600 transition-all">
                  View Profile <span className="transition-transform group-hover:translate-x-1">→</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <ProfilePage data={dataAnggota.find(a => a.id === currentPage)} onBack={() => setCurrentPage('home')} />
      )}
    </div>
  );
}
